const materialGuides=[["Primo fasciame","Tiglio o legno previsto dal kit","Facile da lavorare; controlla spessore e larghezza reali. La sostituzione deve rispettare i piani."],["Secondo fasciame","Noce, pero o essenza prevista","Confronta spessore, fibra e colore; prova colla e finitura su uno scarto."],["Curvatura","Piegalistelli e dima","Preferisci prove su ritagli, curvatura graduale e protezione dal calore."],["Incollaggio legno","Colla vinilica per legno","Adatta a molti giunti legno-legno; verifica tempi di presa e compatibilità."],["Incollaggio minuteria","Adesivo compatibile con entrambi i materiali","Per metallo e legno scegli in base alle istruzioni; evita eccessi e contatto con pelle e occhi."],["Morsetti","Morsetti piccoli e protezioni","Distribuisci la pressione senza imprimere segni sul fasciame."],["Levigatura","Tamponi e abrasivi progressivi","Controlla spesso la forma; usa protezione adeguata dalla polvere."],["Alberatura","Cordame, bigotte e bozzelli","Verifica i diametri e le misure nel piano; non acquistare soltanto in base alla scala nominale."],["Finitura","Mordenti e vernici compatibili","Prova su legno di scarto e segui le istruzioni del produttore, con ventilazione."],["Ricambi","Codice prodotto e numero pezzo","Fotografa la tavola e misura il pezzo prima di richiedere un ricambio."]];
function resourceItems(category='',query=''){
 const q=query.trim().toLocaleLowerCase('it');
 const matched=supplierResources.filter(r=>(!category||r.category===category)&&(!q||[r.title,r.category,r.desc].join(' ').toLocaleLowerCase('it').includes(q)));
 return '<p class="muted">'+matched.length+' risorse trovate</p>'+ (matched.map(r=>'<article class="card"><span class="badge">'+esc(r.category)+'</span><h3 class="spaced">'+esc(r.title)+'</h3><p>'+esc(r.desc)+'</p><a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">Apri sito ufficiale ↗</a></article>').join('')||'<div class="card empty">Nessuna risorsa corrispondente.</div>');
}
function resourcesPanel(){
 return '<h1>Manuali e forniture</h1><p>Collegamenti esterni a produttori e fornitori. Nessun acquisto automatico. Prezzi, disponibilità e spedizioni vanno verificati sui siti.</p><div class="card"><label for="resourceCat">Categoria</label><select id="resourceCat"><option value="">Tutte</option>'+[...new Set(supplierResources.map(r=>r.category))].map(x=>'<option>'+esc(x)+'</option>').join('')+'</select><label for="resourceSearch">Cerca risorsa</label><input id="resourceSearch" type="search" placeholder="Es. ricambi, legno, OcCre"></div><div id="resourceResults">'+resourceItems()+'</div><section class="card"><h2>Manuali per singolo modello</h2>'+kits.filter(k=>k.manual).map(k=>'<p><a href="'+esc(k.manual)+'" target="_blank" rel="noopener noreferrer">'+esc(k.maker+' – '+k.name)+' (PDF) ↗</a></p>').join('')+'<small>File ospitati dai rispettivi produttori; aprirli richiede Internet. Verifica versione e codice del kit.</small></section><section class="card"><h2>Guida a materiali e attrezzi</h2>'+materialGuides.map(g=>'<details class="step"><summary>'+esc(g[0])+' — '+esc(g[1])+'</summary><p>'+esc(g[2])+'</p></details>').join('')+'</section><section class="card"><h2>Checklist richiesta ricambio</h2>'+['Marca e codice esatto del kit','Edizione e scala','Numero del pezzo nel manuale','Misure e materiale','Foto del componente e quantità'].map(x=>'<label class="check"><input type="checkbox">'+esc(x)+'</label>').join('')+'<small>Checklist temporanea, non salvata.</small></section>';
}
function refreshResources(){if(tab==='resources'&&$('resourceResults'))$('resourceResults').innerHTML=resourceItems($('resourceCat').value,$('resourceSearch').value)}
document.addEventListener('input',e=>{if(e.target.id==='resourceSearch')refreshResources()});
document.addEventListener('change',e=>{if(e.target.id==='resourceCat')refreshResources()});


