function mastValue(v,scale){return Number.isFinite(v)&&v>0&&Number.isInteger(scale)&&scale>0&&scale<=10000?v/scale:null}
function mastCalc(){const n=Number($('mastDen').value),l=mastValue(Number($('mastRealLength').value),n),d=mastValue(Number($('mastRealDiameter').value),n);$('mastMeasureResult').textContent=l===null||d===null?'Inserisci misure positive e scala valida': 'Lunghezza '+fmt(l)+' mm · Diametro '+fmt(d)+' mm'}
function mastPanel(){
const i=mastIndex,l=mastCourse[i];
return '<button class="secondary" data-go="academy">← Accademia</button><section class="hero"><h1>Alberi e pennoni</h1><p>Dal legno grezzo all’alberatura pronta per le manovre. Un passaggio alla volta.</p></section><section class="card"><label for="mastSelect">Scegli la fase ('+(i+1)+'/'+mastCourse.length+')</label><select id="mastSelect">'+mastCourse.map((x,j)=>'<option value="'+j+'" '+(i===j?'selected':'')+'>'+(j+1)+'. '+esc(x[0])+'</option>').join('')+'</select></section><section class="card"><h2>'+esc(l[0])+'</h2><p>'+esc(l[1])+'</p>'+mastDiagram(l[5])+'<h3>Cosa comprare o preparare</h3><p>'+esc(l[2])+'</p><h3>Come lavorare</h3><p>'+esc(l[3])+'</p><h3>Controllo prima di avanzare</h3><p>'+esc(l[4])+'</p><div class="row">'+(i>0?'<button class="secondary" data-mast-step="-1">← Indietro</button>':'')+(i<mastCourse.length-1?'<button data-mast-step="1">Prossima fase →</button>':'<button data-go="rigging">Passa al cordame →</button>')+'</div></section><section class="card"><h2>Calcola le quote in scala</h2><p>Solo per misure reali documentate, in millimetri. Non ridurre nuovamente quote già in scala.</p><label for="mastRealLength">Lunghezza reale (mm)</label><input type="number" id="mastRealLength" value="18000" min="1" step="any"><label for="mastRealDiameter">Diametro reale (mm)</label><input type="number" id="mastRealDiameter" value="480" min="1" step="any"><label for="mastDen">Scala 1:N</label><input type="number" id="mastDen" value="64" min="1" step="1"><p id="mastMeasureResult" class="big">Lunghezza 281,25 mm · Diametro 7,5 mm</p><small>Esempio modificabile. Le quote reali variano con il progetto.</small></section><section class="card"><h2>Prodotti e manuali</h2>'+materialLinks('timber tools measure glue dye varnish')+'<p><a href="https://www.manualslib.com/manual/1442461/Model-Shipways-Rattlesnake-Massachusetts-Privateer.html?page=27" target="_blank" rel="noopener noreferrer">Rattlesnake – costruzione alberi e pennoni ↗</a></p><p><a href="https://www.manualslib.com/manual/1087510/Model-Shipways-Charles-W-Morgan.html?page=26" target="_blank" rel="noopener noreferrer">Charles W. Morgan – lavorazione delle aste ↗</a></p><button class="secondary" data-go="materials">Legni e finiture</button><button class="secondary spaced" data-go="rigging">Cordame e manovre</button></section>';
}
document.addEventListener('input',e=>{if(tab==='masts'&&['mastRealLength','mastRealDiameter','mastDen'].includes(e.target.id))mastCalc()});
document.addEventListener('change',e=>{if(tab==='masts'&&e.target.id==='mastSelect'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=0&&n<mastCourse.length){mastIndex=n;render();window.scrollTo(0,0)}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(tab!=='masts'||!b||b.dataset.mastStep===undefined)return;const n=mastIndex+Number(b.dataset.mastStep);if(Number.isInteger(n)&&n>=0&&n<mastCourse.length){mastIndex=n;render();window.scrollTo(0,0)}});


const airCourse=[["Scegliere l’aerografo","Scegli uno strumento versatile per scafi e dettagli.","Aerografo a doppia azione con serbatoio superiore; ugello circa 0,3–0,35 mm come scelta iniziale indicativa. Esempi: Iwata NEO CN, Eclipse HP-CS. Un ugello più grande può facilitare fondi e superfici ampie; quelli molto fini richiedono maggiore pratica.","Verifica disponibilità di aghi, ugelli, guarnizioni, compatibilità dei raccordi e pressione ammessa. Doppia azione: premi per l'aria, tira indietro per il colore.","Non comprare un ugello finissimo solo perché sembra più preciso. La scelta dipende da viscosità, dettaglio e portata.","brush"],["Compressore e collegamenti","Ottieni aria stabile, pulita e regolabile.","Compressore per aerografo con regolatore e manometro, separatore di condensa, tubo compatibile; serbatoio opzionale utile per stabilità e riduzione dei cicli.","Collega secondo manuali, verifica perdite e scarica la condensa come indicato dal costruttore. Regola con aria in uscita, non a riposo. Non superare le pressioni ammesse.","Il manometro deve essere leggibile durante la spruzzatura. Non modificare serbatoi o valvole di sicurezza.","compressor"],["Sicurezza e postazione","Evita di respirare aerosol anche con colori ad acqua.","Cabina con aspirazione ed espulsione sicura all'esterno, protezione respiratoria scelta secondo SDS e rischio, occhiali, guanti compatibili, supporto per pezzi e contenitore di pulizia.","Scegli acrilici per modellismo all'acqua privi di isocianati e adatti alla spruzzatura; verifica SDS. Usa aspirazione efficace, tieni lontani altri occupanti e animali; non lavorare in cucina. Mantieni la protezione finché la nebbia è eliminata.","Evita vernici 2K con isocianati e solventi infiammabili in un impianto domestico non idoneo. Una mascherina antipolvere non protegge dai vapori. Se non hai controlli adeguati, usa il pennello.","booth"],["Preparare lo scafo","Ottieni una superficie regolare senza perdere dettagli.","Tampone, abrasivi fini secondo fondo, aspirazione polvere, panno privo di peluria, supporto stabile.","Controlla che colla e riparazioni siano mature. Leviga gradualmente, elimina residui di colla e polvere. Maschera superfici destinate all'incollaggio. Su legno naturale da mordenzare, evita primer coprenti o turapori incompatibili.","Prova il ciclo su uno scarto della stessa essenza e già incollato. Il colore non nasconde avvallamenti strutturali.","prep"],["Primer e fondo","Crea una base compatibile con il colore coprente.","Primer dichiarato adatto al supporto e all'aerografo; acrilico per legno o per metallo secondo il pezzo; campione.","Prepara il campione, mescola e diluisci soltanto come previsto dalla scheda. Spruzza mani leggere con estrazione. Lascia maturare secondo prodotto; leviga soltanto se previsto.","Non usare primer per plastica come garanzia di adesione al legno. Non applicarlo prima di un mordente penetrante senza conferma.","layers"],["Scegliere colori e diluenti","Distingui colore pronto, colore denso, primer e trasparente.","Vallejo Model Air, Airbrush Thinner 71.061/71.261, Flow Improver 71.262 opzionale, bicchierino e pipette dedicate.","Model Air nasce per aerografo e spesso non richiede diluizione. Se serve, la guida indica 3 parti colore e 1 di thinner. Per Model Color la guida storica mostra un esempio 1:1 con thinner: verifica formula ed etichetta attuali. Il flow improver non è un sostituto universale del diluente.","Non aggiungere alcol o solventi domestici senza autorizzazione del produttore. Mescola su campione e non contaminare le bottiglie.","mix"],["Impostare pressione e distanza","Trova un getto uniforme senza colature.","Aerografo, manometro, cartoncino e scarto di legno preparato.","Per Model Air la guida suggerisce 15–25 PSI. Prova circa 20 PSI con aria in movimento se compatibile con il tuo aerografo. Inizia a circa 8–15 cm per campiture come prova orientativa; avvicinati per dettagli riducendo portata e, se appropriato, pressione. Modifica una variabile alla volta.","La distanza e la pressione non sono universali. Il getto deve essere uniforme, senza spruzzi grossi o eccessiva nebbia.","distance"],["Imparare la doppia azione","Controlla il flusso senza accumulare colore.","Acqua per prova iniziale, poi colore compatibile su campioni, cabina aspirante.","Premi il grilletto per l'aria, muovi la mano, tira leggermente indietro per erogare colore, chiudi prima il colore e poi l'aria. Esercitati con punti, linee parallele e sfumature su cartoncino; verifica poi su legno preparato.","Non fermarti sul pezzo mentre eroghi colore. Non toccare il modello con la punta.","exercise"],["Verniciare uno scafo","Stendi il colore coprente in modo uniforme.","Supporto girevole manuale, colore preparato, campione e maschere.","Inizia e termina le passate fuori dal bordo. Muovi l'aerografo a velocità costante, orientato verso la superficie locale; sovrapponi leggermente le passate. Applica più strati sottili lasciando asciugare fra uno e l'altro secondo scheda.","Non cercare copertura piena in una sola mano. Evita accumuli vicino a spigoli e decorazioni.","passes"],["Linea di galleggiamento","Ottieni un confine netto tra due colori.","Dima di altezza, nastro modellistico a bassa adesività, carta di mascheratura.","Metti lo scafo nella posizione di riferimento del piano. Traccia la linea, verifica i due lati. Sul colore di base maturato prova il nastro su scarto, poi maschera senza pieghe. Spruzza strati leggeri senza insistere verso il bordo; rimuovi secondo il ciclo scelto.","Non usare una linea orizzontale arbitraria rispetto al basamento. Non mascherare finiture ancora morbide.","mask"],["Dettagli, sfumature e invecchiamento","Riproduci effetti realistici senza esagerare.","Colori compatibili, campioni, pennelli fini, maschere e riferimenti storici.","Prova variazioni leggere di tono su scarto. Per dettagli riduci la portata e usa passate controllate. Per velieri storici scegli effetti coerenti con il progetto; per navi moderne documenta eventuali segni di usura. Usa il pennello dove più preciso.","Le venature naturali del legno non richiedono sempre pittura; non trasformare ogni modello in una nave usurata.","shade"],["Trasparente opaco, satinato e lucido","Proteggi la superficie con il grado di brillantezza desiderato.","Trasparente dichiarato spruzzabile e compatibile con il colore o mordente; campione.","Attendi maturazione del fondo. Mescola secondo scheda e prova l'intero ciclo. Spruzza mani sottili senza accumulare materiale; rispetta essiccazione e indurimento. Per legno a vista considera anche l'applicazione a pennello.","Non introdurre nell'aerografo una vernice per pennello se il produttore non ne consente la spruzzatura. Evita 2K domestici.","finish"],["Pulizia e manutenzione","Evita intasamenti e danni alla punta.","Cleaner specifico, contenitore di raccolta con filtro, pennello morbido, panno, ricambi del modello.","Tra colori svuota la tazza, rimuovi residui con cleaner compatibile e scarica nel contenitore con aspirazione. A fine sessione segui la pulizia del costruttore. Prima di smontare spegni e depressurizza; maneggia l'ago con cura e non forzare l'ugello.","Non immergere tutto il corpo in solvente. Non forzare strumenti nel foro; non spruzzare cleaner nell'aria della stanza. Smaltisci residui secondo etichetta.","clean"]],airDefects=[["Colature","Troppo colore, mano lenta o troppo vicina.","Interrompi; lascia maturare, correggi su campione e poi leviga se compatibile. Riduci portata, muovi più uniformemente."],["Superficie granulosa","Getto troppo secco, distanza eccessiva o miscela non adatta.","Controlla diluizione, distanza e pressione su scarto; non correggere aggiungendo indiscriminatamente solvente."],["Schizzi e getto intermittente","Punta sporca, colore non omogeneo, ugello o alimentazione.","Ferma e pulisci secondo manuale, verifica tenuta e condensa; prova con cleaner compatibile prima del colore."],["Ragnatele di colore","Miscela troppo fluida per la portata, pressione o distanza.","Riduci colore e prova pressione minore se ammessa; modifica una variabile alla volta."],["Bolle nella tazza","Possibile ugello ostruito, raccordo o tenuta difettosi.","Ferma, depressurizza, verifica pulizia e montaggio secondo il produttore; non stringere eccessivamente."],["Vernice sollevata dal nastro","Fondo non maturato, adesione insufficiente o nastro aggressivo.","Prova il ciclo e il nastro su scarto, rispetta maturazione e ripara il fondo prima di riverniciare."],["Condensa nel getto","Acqua nel sistema aria.","Controlla separatore e scarico serbatoio secondo manuale; non aprire parti pressurizzate."],["Punta secca (tip dry)","Colore che asciuga sulla punta dell'ago.","Ferma e pulisci delicatamente secondo manuale. Valuta flow improver compatibile e regolazioni su scarto."]];
