function airDiagram(k){
 const ink='#243c45',green='#216764',red='#a43e32',wood='#d8b17d';
 const t=(x,y,v,c=ink,n=12)=>'<text x="'+x+'" y="'+y+'" text-anchor="middle" fill="'+c+'" font-size="'+n+'" font-weight="600">'+esc(v)+'</text>';
 const p=(d,f='none',c=ink,w=2)=>'<path d="'+d+'" fill="'+f+'" stroke="'+c+'" stroke-width="'+w+'" stroke-linejoin="round"/>';
 const rect=(x,y,w,h,f)=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="3" fill="'+f+'" stroke="'+ink+'"/>';
 const line=(x,y,X,Y,c=green)=>p('M'+x+' '+y+'L'+X+' '+Y,'none',c);
 const brush=(x,y)=>'<g transform="translate('+x+' '+y+')">'+p('M0 18L25 8H128Q142 20 128 32H25Z','#c4d0d1')+p('M36 8L30 -22H65L58 8','#e2e8e6')+rect(78,-3,11,12,'#b5c4c6')+rect(84,31,12,15,'#b5c4c6')+'</g>';
 let z='';
 switch(k){
 case 'brush':z=brush(85,103)+t(125,30,'Tazza colore')+line(125,34,130,81)+t(240,48,'Grilletto')+line(220,53,169,103)+t(42,167,'Ugello')+line(52,155,85,121)+t(226,191,'Attacco aria')+line(215,177,175,147);break;
 case 'compressor':z=rect(18,116,120,65,'#a8b9b8')+rect(32,83,88,31,'#c6d1cf')+'<circle cx="141" cy="92" r="19" fill="white" stroke="'+ink+'"/>'+line(141,92,151,82)+rect(165,106,24,39,'#e6f2ed')+p('M160 92H177V105M177 145Q205 180 245 145V120', 'none',green,4)+brush(205,73)+t(80,202,'Compressore')+t(144,56,'Manometro')+t(184,164,'Filtro',green,11);break;
 case 'booth':z=p('M35 177V35H300V177Z','#dae6e0')+rect(128,46,120,31,'#a7bcba')+p('M185 46V17H328','none',green,9)+p('M105 133L160 89M175 133V89M245 133L210 89','none',green,3)+p('M70 153Q175 183 278 153L250 177H98Z',wood)+t(185,66,'Filtro / aspirazione')+t(265,13,'Esterno',green)+t(175,205,'Nebbia catturata alla fonte');break;
 case 'prep':z=p('M20 85Q175 125 330 85Q300 164 175 169Q50 164 20 85Z',wood)+rect(78,73,125,19,'#aebfc0')+t(140,47,'Tampone lungo')+line(140,51,140,73)+t(175,202,'Superficie pulita e regolare',green);break;
 case 'layers':case 'finish':z=rect(37,135,276,32,wood)+rect(37,120,276,15,'#b3b6af')+rect(37,98,276,22,'#386e74')+rect(37,90,276,8,'#dce8e4')+t(175,65,'Trasparente se previsto')+line(175,68,175,90)+t(175,112,'Colore','white')+t(175,131,'Fondo',ink,10)+t(175,156,'Legno')+t(175,202,'Strati schematici, non in scala');break;
 case 'mix':z=rect(35,52,80,105,'#386e74')+rect(55,29,40,23,'#c5cdcb')+rect(140,87,57,70,'#e1e9e5')+rect(153,66,31,21,'#c5cdcb')+p('M230 80L242 166H308L320 80','#fff9eb')+p('M241 126H309L304 161H246Z','#75a1a0')+t(75,181,'3 parti colore')+t(169,181,'1 parte thinner')+t(275,181,'Miscela')+t(175,211,'Model Air: solo se serve diluire',green);break;
 case 'distance':z=brush(70,73)+p('M70 91L20 60M70 91L20 125','none',green,2)+rect(12,43,8,110,wood)+line(20,169,70,169)+line(20,162,20,176)+line(70,162,70,176)+t(124,194,'Distanza: prova su scarto')+t(250,47,'15–25 PSI',green)+t(250,63,'Model Air',green,11);break;
 case 'exercise':z=rect(25,25,300,156,'#fffdf5')+[65,100,135,170,205,240,275].map(x=>'<circle cx="'+x+'" cy="57" r="3.5" fill="'+green+'"/>').join('')+[90,110,130].map(y=>p('M50 '+y+'H300','none',green,3)).join('')+p('M50 153H300','none','#80a6a3',10)+t(175,205,'Punti → linee → passate uniformi');break;
 case 'passes':z=p('M22 62Q175 105 328 62Q300 175 175 182Q50 175 22 62Z',wood)+[88,112,136].map(y=>p('M40 '+y+'Q175 '+(y+20)+' 310 '+y,'none','#659995',14)).join('')+t(175,31,'Passate leggermente sovrapposte')+t(175,211,'Muovi prima di erogare colore',green);break;
 case 'mask':z=p('M22 55Q175 85 328 55Q300 163 175 179Q50 163 22 55Z','#e6d6ae')+p('M44 115Q175 138 306 115Q276 169 175 179Q74 169 44 115Z','#9f4c37')+p('M44 115Q175 138 306 115','none','#f0c94d',8)+t(175,28,'Nastro sulla linea da piano')+line(175,35,175,125)+t(175,209,'Fondo maturato prima di mascherare',green);break;
 case 'shade':z=rect(25,45,300,115,'#b7a47a')+[0,1,2,3,4,5,6,7].map(i=>'<rect x="'+(30+i*36)+'" y="50" width="36" height="105" fill="#4d5f50" opacity="'+(0.04+i*0.055)+'"/>').join('')+t(175,25,'Variazioni leggere di tono')+t(175,191,'Prova su campione',green);break;
 case 'clean':z=brush(40,65)+rect(185,113,105,78,'#cbdedb')+rect(177,102,120,14,'#a6b9b8')+p('M110 111Q165 153 225 114','none',green,3)+t(235,87,'Raccolta filtrata')+t(175,213,'Pulizia con aspirazione attiva',green);break;
 }
 return '<figure class="study-figure"><svg viewBox="0 0 350 230" role="img" aria-label="Schema illustrativo della fase '+esc(k)+'">'+z+'</svg><figcaption>Schema orientativo per comprendere la tecnica; segui il manuale dell’attrezzatura e la scheda del prodotto.</figcaption></figure>';
}
function airMix(total,paint,thin){if(![total,paint,thin].every(Number.isFinite)||total<=0||paint<=0||thin<0||total>1000)return null;return [total*paint/(paint+thin),total*thin/(paint+thin)]}
function airCalculate(){
const v=airMix(Number($('airTotal').value),Number($('airPaint').value),Number($('airThin').value)),psi=Number($('airPsi').value);
$('airMixResult').textContent=v?'Colore '+fmt(v[0],2)+' ml · Diluente '+fmt(v[1],2)+' ml':'Inserisci valori validi';
$('airBar').textContent=Number.isFinite(psi)&&psi>0&&psi<=100?fmt(psi*.0689476,2)+' bar':'Inserisci PSI validi';
}
function airPanel(){
const i=airIndex,l=airCourse[i];return '<button class="secondary" data-go="academy">← Accademia</button><section class="hero"><h1>Aerografo e verniciatura</h1><p>Da zero a uno scafo verniciato: attrezzatura, prove, finiture e manutenzione.</p></section><section class="card"><label for="airSelect">Fase '+(i+1)+' / '+airCourse.length+'</label><select id="airSelect">'+airCourse.map((r,j)=>'<option value="'+j+'" '+(i===j?'selected':'')+'>'+(j+1)+'. '+esc(r[0])+'</option>').join('')+'</select></section><section class="card"><h2>'+esc(l[0])+'</h2><p>'+esc(l[1])+'</p>'+airDiagram(l[5])+'<h3>Cosa comprare o preparare</h3><p>'+esc(l[2])+'</p><h3>Come fare</h3><p>'+esc(l[3])+'</p><h3>Controllo ed errori da evitare</h3><p>'+esc(l[4])+'</p><div class="row">'+(i>0?'<button class="secondary" data-air-step="-1">← Indietro</button>':'')+(i<airCourse.length-1?'<button data-air-step="1">Prossima fase →</button>':'<button data-go="materials">Materiali e finiture</button>')+'</div></section><section class="card"><h2>Calcolatore diluizione</h2><p>Imposta le parti secondo la scheda. Esempio Model Air, se necessario: 3:1 colore/diluente. Per colore pronto senza diluire imposta 0 parti diluente.</p><label for="airTotal">Miscela finale (ml)</label><input id="airTotal" type="number" min="0.1" max="1000" step="any" value="4"><label for="airPaint">Parti colore</label><input id="airPaint" type="number" min="0.1" step="any" value="3"><label for="airThin">Parti diluente</label><input id="airThin" type="number" min="0" step="any" value="1"><p id="airMixResult" class="big" aria-live="polite">Colore 3 ml · Diluente 1 ml</p><label for="airPsi">Pressione (PSI)</label><input id="airPsi" type="number" min="1" max="100" step="any" value="20"><p id="airBar" aria-live="polite">1,38 bar</p><small>Conversione, non autorizzazione a usare la pressione: rispetta il limite dell’attrezzatura.</small></section><section class="card"><h2>Risolvi i problemi</h2>'+airDefects.map(r=>'<details><summary>'+esc(r[0])+'</summary><p><b>Possibile causa:</b> '+esc(r[1])+'</p><p><b>Come intervenire:</b> '+esc(r[2])+'</p></details>').join('')+'</section><section class="card"><h2>Istruzioni ufficiali e acquisti</h2>'+airLinks.map(r=>'<p><a href="'+esc(r[1])+'" target="_blank" rel="noopener noreferrer">'+esc(r[0])+' ↗</a></p>').join('')+materialLinks('paint supply')+'<small>Prezzi e disponibilità da verificare; nessun acquisto automatico. I riferimenti sono online.</small></section>';
}
document.addEventListener('input',e=>{if(tab==='airbrush'&&['airTotal','airPaint','airThin','airPsi'].includes(e.target.id))airCalculate()});
document.addEventListener('change',e=>{if(tab==='airbrush'&&e.target.id==='airSelect'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=0&&n<airCourse.length){airIndex=n;render();window.scrollTo(0,0)}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(tab!=='airbrush'||!b||b.dataset.airStep===undefined)return;const n=airIndex+Number(b.dataset.airStep);if(Number.isInteger(n)&&n>=0&&n<airCourse.length){airIndex=n;render();window.scrollTo(0,0)}});


const advancedLessons=[["Lavorazione dell’ottone","Piegare, forare e rifinire piccoli accessori.","Lamierino o filo di ottone nella sezione prevista, pinze lisce, lime, morsa con ganasce protette, occhiali.","Trasferisci la sagoma su carta; prova una piega su ritaglio. Taglia con utensile adatto, rifinisci i bordi e piega su dima. Fissa il pezzo per forare; elimina le bave. Prova l’accessorio sul modello prima di dipingere.","Nessuna bava, spigolo pericoloso o deformazione. Non scaldare il metallo senza formazione e attrezzatura adatta.","metal"],["Saldatura dolce di piccoli accessori","Unire parti di ottone fuori dal modello.","Saldatore regolabile, lega senza piombo e flussante compatibile, supporto termoresistente, estrazione localizzata dei fumi.","Leggi manuale e schede di sicurezza. Prepara e pulisci i giunti; blocca i pezzi in dima resistente al calore. Esercitati su scarti: scalda il giunto e usa una quantità minima di lega secondo le istruzioni del prodotto. Lascia raffreddare; pulisci i residui secondo il flussante.","Fai una prova di tenuta su scarto. Mai saldare sullo scafo in legno. I fumi del flussante possono provocare asma: se manca estrazione idonea, preferisci accessori pronti o giunti a freddo.","solder"],["Tornitura del legno","Ricavare profili di aste e accessori con attrezzatura idonea.","Mini tornio per legno con protezioni, utensili del produttore, occhiali o visiera, estrazione polvere, calibro.","Impara su grezzi con istruzioni del costruttore o istruttore. Verifica fissaggio, supporto e velocità consentita; usa utensili affilati e passate leggere. Ferma la macchina prima di misurare o regolare. Per iniziare, puoi ottenere molte forme con sagomatura manuale.","Niente guanti vicino a parti rotanti, capelli o abiti liberi. Non utilizzare un trapano improvvisato come tornio. Non lavorare pezzi lesionati.","lathe"],["Cannoni e affusti in miniatura","Riprodurre accessori puramente decorativi.","Cannoni modellistici solidi e inerti oppure tondini di legno, listelli per affusti, ruote decorative, colle e colori compatibili.","Ricava solo le dimensioni esterne dal piano. Sagoma un cilindro pieno decorativo senza canna funzionale. Prepara le fiancate dell’affusto con dima, asse e ruote secondo il disegno del modello. Monta a secco e prova nelle aperture dello scafo.","Accessori esclusivamente ornamentali, proporzionati e stabili. Nessuna parte destinata a sparare o contenere cariche.","gun"],["Realizzazione delle vele","Preparare vele in tessuto proporzionate alla scala.","Tela sottile di cotone o batista, carta per sagome, ago fine, filo, forbici, righello.","Stampa o traccia la sagoma dal piano calibrato; prova lavaggio e ritiro su scarto. Segna cuciture e orli secondo scala; taglia con margine appropriato. Cuci o incolla gli orli con metodo provato, realizza i rinforzi documentati e monta sui pennoni con legature previste.","Trama e cuciture non devono risultare sovradimensionate. Evita di bagnare vele già montate; se il modello è senza vele, segui il piano delle manovre corrispondente.","sail"],["Fabbricazione del cordame","Produrre corde in scala con una commettitrice.","Commettitrice manuale da modellismo, filo regolare, supporti, calibro, ganci e dima secondo macchina.","Scegli tre o quattro trefoli secondo il tipo storico. Fissali alla macchina e mantienili sotto tensione uniforme. Torci i trefoli nel verso previsto, poi accompagnali nella commettitura opposta con la guida della macchina. Prova prima un tratto corto, misura il diametro e annota materiale, numero di fili e risultato.","La corda deve essere uniforme e non svolgersi facilmente. Attenzione a ganci e parti rotanti: segui le istruzioni della macchina. Non assumere diametri teorici senza misurazione.","rope"],["Bozzelli e bigotte","Creare piccoli elementi con sagome ripetibili.","Legno a fibra fine, dima, microtrapano manuale, lime fini, carta abrasiva, supporto.","Ricava forma e numero di fori dal piano. Lavora da un listello più lungo ben bloccato, segna le posizioni e fora con utensile adatto; sagoma l’esterno prima di separare i pezzi. Rifinisci, arrotonda le sedi della legatura solo dove previsto e prova il cordame.","Fori puliti e ripetibili; non tenere un pezzo minuscolo fra le dita mentre fori. Il cordame deve scorrere senza danneggiarsi.","block"],["Sculture e decorazioni","Riprodurre fregi e modanature.","Pero o legno fine da intaglio, sagome, utensili piccoli affilati, supporto stabile, abrasivi fini.","Studia il motivo e la scala. Traccia il contorno, prepara un campione ingrandito, poi ripeti alla scala effettiva. Rimuovi materiale a piccole passate e rifinisci seguendo la fibra. Prova la finitura su scarto.","Non lavorare verso le dita; non asportare dettagli in una sola passata. Per iniziare puoi usare accessori commerciali.","carve"],["Invecchiamento realistico","Dosare patine e variazioni di colore.","Acrilici compatibili, pennelli, campioni, aerografo solo se adeguatamente protetto, riferimenti storici.","Parti da fondo maturato. Su campione prova velature leggere e pennello quasi asciutto; confronta con fotografie e documentazione. Applica effetti solo dove coerenti con materiali e uso della nave.","Controlla l’aspetto alla distanza normale di osservazione. Non simulare ruggine sul legno o effetti casuali. Consulta il corso aerografo per sicurezza.","weather"],["Restauro dei modelli","Documentare, stabilizzare e riparare senza perdere informazioni.","Fotocamera, pennello morbido, supporti, materiali compatibili, contenitori per parti staccate.","Fotografa prima di intervenire. Identifica materiali, parti mobili e danni; conserva i frammenti. Rimuovi solo polvere libera con metodo delicato. Prova ogni intervento su zona nascosta; ripara con materiali compatibili e documenta.","Non usare solventi, acqua o colle su materiali sconosciuti. Per modelli antichi o di valore consulta un conservatore.","restore"],["Modellismo d’arsenale","Comprendere la costruzione strutturale a coste.","Piani completi di qualità, sagome calibrate, legno da piano, attrezzi di precisione e scaletto.","Studia monografia e sezioni; verifica riferimenti longitudinali e trasversali. Prepara scaletto e campioni di coste. Riproduci ciascuna struttura secondo progetto, controlla allineamenti e ordine di montaggio. Inizia con una sezione di prova prima di una nave completa.","Non ricavare ordinate o incastri da illustrazioni generiche. È una tecnica avanzata: richiede piani strutturali completi.","arsenal"]];
const paintPresets=[
['Legno naturale','#91613c','#85563a','#d9bd8d','#e9dfc8','#573c28'],
['Veliero scuro e ocra','#252a2b','#913d2e','#d4b88b','#e8dfca','#bc9346'],
['Scafo chiaro','#eee8d9','#914536','#d5bf99','#f5f0dd','#374748'],
['Blu e crema','#294b66','#74392e','#d9bb87','#f2e6ce','#e4d7b6']
];
let paintChoice=paintPresets[0].slice(1);
function paintSafe(c){return typeof c==='string'&&/^#[0-9a-fA-F]{6}$/.test(c)?c:'#91613c'}
function shipPaintSvg(c){
const [hull,lower,deck,sails,trim]=c.map(paintSafe);
return '<svg viewBox="0 0 350 252" role="img" aria-label="Anteprima schematica del veliero nei colori scelti"><rect width="350" height="252" rx="10" fill="#edf1ef"/><path d="M30 174Q125 198 326 153L302 209Q180 239 65 208Z" fill="'+lower+'" stroke="#543c2b" stroke-width="1.4"/><path d="M30 137Q150 157 326 115V153Q125 198 30 174Z" fill="'+hull+'" stroke="#543c2b" stroke-width="1.4"/><path d="M30 137L55 125L326 106V115Q150 157 30 137Z" fill="'+deck+'" stroke="#543c2b"/><path d="M30 160Q150 183 326 137" fill="none" stroke="'+trim+'" stroke-width="5"/>'+[90,125,160,195,230,265,300].map(x=>'<rect x="'+x+'" y="'+(146-(x-90)*.07)+'" width="11" height="10" fill="#2e2925" stroke="'+trim+'"/>').join('')+[[103,40,62],[184,18,76],[266,47,52]].map(([x,y,w])=>'<path d="M'+x+' '+y+'V143" stroke="#775638" stroke-width="4"/><path d="M'+(x-w/2)+' '+(y+18)+'H'+(x+w/2)+'" stroke="#775638" stroke-width="4"/><path d="M'+(x-w/2)+' '+(y+20)+'Q'+x+' '+(y+29)+' '+(x+w/2)+' '+(y+20)+'L'+(x+w/2-5)+' '+(y+66)+'Q'+x+' '+(y+78)+' '+(x-w/2+5)+' '+(y+66)+'Z" fill="'+sails+'" stroke="#a19783"/>').join('')+'<path d="M30 140L6 114M103 40L30 137M184 18L103 137M266 47L184 140" stroke="#795638" stroke-width="1" fill="none"/></svg>';
}
function colorPanel(){
const labels=['Scafo','Opera viva','Ponte','Vele','Cinte e decorazioni'];
return '<button class="secondary" data-go="academy">← Accademia</button><section class="hero"><h1>Simulatore dei colori</h1><p>Prova gli abbinamenti prima di acquistare i colori.</p></section><section class="card"><label for="paintPreset">Combinazioni di esempio</label><select id="paintPreset"><option value="">Personalizzata</option>'+paintPresets.map((r,i)=>'<option value="'+i+'">'+esc(r[0])+'</option>').join('')+'</select><div id="shipPaintPreview" class="paint-preview">'+shipPaintSvg(paintChoice)+'</div>'+labels.map((l,i)=>'<label class="paint-field" for="paintColor'+i+'"><span>'+esc(l)+'</span><input id="paintColor'+i+'" type="color" value="'+paintSafe(paintChoice[i])+'" data-paint-index="'+i+'"><output id="paintHex'+i+'">'+paintSafe(paintChoice[i])+'</output></label>').join('')+'<button class="easy-action" data-paint-save>Scarica la scheda colori</button><small>Anteprima 2D generica, non una ricostruzione della nave né un colore calibrato. Le tonalità reali dipendono dal legno, dal primer e dalla luce. Gli esempi non certificano l’accuratezza storica.</small></section><section class="card"><h2>Prima di verniciare</h2><p>Confronta la combinazione con i riferimenti storici; prova mordente, colore e trasparente su campioni dello stesso legno. Il codice esadecimale non corrisponde automaticamente a una vernice commerciale.</p><button data-go="airbrush">Corso aerografo</button><button class="secondary spaced" data-go="materials">Materiali e finiture</button></section>';
}
function advancedPanel(){return '<button class="secondary" data-go="academy">← Accademia</button><section class="hero"><h1>Laboratorio avanzato</h1><p>11 tecniche specialistiche per passare dal kit all’autocostruzione.</p></section><section class="card"><h2>Prima di cominciare</h2><p>Prova ogni lavorazione su scarti. Acquista attrezzi soltanto quando servono. Le tecniche con macchine, calore e sostanze chimiche richiedono istruzioni specifiche, protezioni e formazione adeguate.</p></section>'+advancedLessons.map((r,i)=>'<details class="card"><summary><b>'+(i+1)+'. '+esc(r[0])+'</b></summary><p>'+esc(r[1])+'</p><h3>Materiali e attrezzi</h3><p>'+esc(r[2])+'</p><h3>Procedura</h3><p>'+esc(r[3])+'</p><h3>Controllo e sicurezza</h3><p>'+esc(r[4])+'</p></details>').join('')+'<section class="card"><h2>Approfondimenti</h2><p><a href="https://syrenshipmodelcompany.com/ropewalk.php" target="_blank" rel="noopener noreferrer">Syren – commettitrice e istruzioni</a></p><p><a href="https://www.manualslib.com/manual/789534/Model-Shipways-H-M-S-Bounty-S-Launch-1789.html?page=18" target="_blank" rel="noopener noreferrer">Model Shipways – preparazione vele e aste</a></p><p><a href="https://www.hse.gov.uk/asthma/solderers.htm" target="_blank" rel="noopener noreferrer">HSE UK – rischi dei fumi di saldatura</a></p><p><a href="https://www.hse.gov.uk/woodworking/hazard.htm" target="_blank" rel="noopener noreferrer">HSE UK – polvere e prodotti per legno</a></p>'+materialLinks('tools timber supply')+'</section>';
}
function paintRefresh(){ $('shipPaintPreview').innerHTML=shipPaintSvg(paintChoice);paintChoice.forEach((c,i)=>{$('paintColor'+i).value=c;$('paintHex'+i).textContent=c})}
document.addEventListener('input',e=>{if(tab!=='colors'||e.target.dataset.paintIndex===undefined)return;const i=Number(e.target.dataset.paintIndex);if(Number.isInteger(i)&&i>=0&&i<5){paintChoice[i]=paintSafe(e.target.value);$('paintPreset').value='';paintRefresh()}});
document.addEventListener('change',e=>{if(tab==='colors'&&e.target.id==='paintPreset'&&e.target.value!==''){const i=Number(e.target.value);if(Number.isInteger(i)&&paintPresets[i]){paintChoice=paintPresets[i].slice(1);paintRefresh()}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(tab!=='colors'||!b||b.dataset.paintSave===undefined)return;const html='<!doctype html><html lang="it"><meta charset="utf-8"><title>Scheda colori Naval Intelligence</title><h1>Scheda colori indicativa</h1>'+shipPaintSvg(paintChoice)+'<p>'+['Scafo','Opera viva','Ponte','Vele','Cinte'].map((n,i)=>n+': '+paintSafe(paintChoice[i])).join(' · ')+'</p><p>Anteprima generica: verificare su campioni reali.</p></html>';const u=URL.createObjectURL(new Blob([html],{type:'text/html'}));const link=document.createElement('a');link.href=u;link.download='naval-scheda-colori.html';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});

function academy(){if(lessonId!==null){const l=lessons[lessonId];return `<button class="secondary" data-go="academy">← Accademia</button><div class="card lesson"><span class="badge">${l.level} · Lezione ${lessonId+1}/${lessons.length}</span><h1 class="spaced">${l.title}</h1>${studyInfo(lessonId)}${academyArtMap[lessonId]?academyArt(lessonId):''}${lessonId===9?mastDiagram('anatomy'):studyDrawing(lessonId)}${lessonId===9?'<button class="easy-action" data-go="masts">Impara a preparare alberi e pennoni →</button>':''}${workshopLesson(lessonId)}${lessonId===8?'<button class="easy-action" data-go="airbrush">Corso aerografo e verniciatura →</button>':''}${[9,20].includes(lessonId)?'<button class="easy-action" data-go="rigging">Corso completo cordame e manovre →</button>':''}<h3>Attrezzi</h3><p>${l.tools}</p><h3 class="spaced">Segui questi passaggi</h3><ol class="study-steps">${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>Controllo qualità</h3><p>${l.check}</p><h3 class="spaced">Errore da evitare</h3><p>${l.error}</p>${studyPractice(lessonId)}<details class="card"><summary>Ripasso: ${l.q}</summary><p>${l.answer}</p></details><button class="easy-action" data-study-next>Completa e vai avanti →</button>${state.done.includes(lessonId)?`<button class="secondary" data-complete="${lessonId}">✓ Già completata — riapri</button>`:''}<p class="muted">Puoi consultare liberamente le altre lezioni dall’elenco. Il completamento guidato richiede la verifica e la prova pratica.</p></div>`}return `<h1>Accademia</h1><div class="card"><h2>Laboratorio avanzato</h2><p>11 tecniche specialistiche: vele, corde, ottone, restauro e molto altro.</p><button class="easy-action" data-go="advanced">Apri laboratorio →</button></div><div class="card"><h2>Simulatore colori</h2><p>Personalizza scafo, opera viva, ponte, vele e decorazioni.</p><button class="easy-action" data-go="colors">Prova i colori →</button></div><div class="card"><h2>Aerografo e verniciatura</h2><p>Impara a preparare, verniciare e rifinire lo scafo.</p><button class="easy-action" data-go="airbrush">Apri corso aerografo →</button></div><div class="card"><h2>Alberi e pennoni</h2><p>Dal tondino grezzo alla preparazione del cordame.</p><button class="easy-action" data-go="masts">Apri corso alberi e pennoni →</button></div><div class="card"><h2>Cordame e manovre</h2><p>Riconosci le cime, segui i percorsi e impara a montarle.</p><button class="easy-action" data-go="rigging">Apri corso cordame →</button></div><div class="card"><h2>Materiali e finiture</h2><p>Impara a scegliere legni, colle, mordenti, vernici e attrezzi.</p><button class="easy-action" data-go="materials">Apri enciclopedia del modellista →</button></div><div class="card"><h2>Non sai da dove iniziare?</h2><button class="easy-action" data-easy-firstlesson>Inizia o riprendi le lezioni →</button></div><p>22 lezioni con disegni, liste acquisti, preparazione dei materiali, esercizi pratici e quiz. Le quattro tavole realistiche sono mantenute. Segui sempre il manuale specifico del tuo kit. Le lezioni 11–20 approfondiscono lo scafo.</p><div class="card"><strong>${state.done.length}/${lessons.length} lezioni completate</strong>${progress(Math.round(state.done.length/lessons.length*100))}<p>Verifiche superate: ${lessons.filter((l,i)=>studyResult(i)).length}/${lessons.length}</p></div><div class="card"><h3>Riferimenti tecnici</h3><p><a href="https://www.modelerscentral.com/model-ship-building/planking-tips-for-building-a-model-ship/" target="_blank" rel="noopener noreferrer">Modelers Central: tecniche di fasciatura</a></p><p><a href="https://www.manualslib.com/manual/1087510/Model-Shipways-Charles-W-Morgan.html?page=12" target="_blank" rel="noopener noreferrer">Model Shipways: fasce, corsi e giunzioni</a></p><small>Consultazione facoltativa online. I disegni e le lezioni dell’app sono originali e generici.</small></div>${lessons.map((l,i)=>`<div class="card"><div class="row between"><span class="badge">${l.level} · ${i+1}</span>${state.done.includes(i)?'<strong>✓ Completata</strong>':''}</div><h3 class="spaced">${l.title}</h3><p class="muted">${studyResult(i)?'✓ Verifica superata · ':''}Disegno, prova pratica e quiz${academyArtMap[i]?' · tavole realistiche':''}</p><button data-lesson="${i}">Apri lezione</button></div>`).join('')}`}

function planWidths(arcs,n,stock){
 if(!Array.isArray(arcs)||arcs.length<2||arcs.length>30||arcs.some(x=>!Number.isFinite(x)||x<=0||x>100000)||!Number.isInteger(n)||n<1||n>1000||!Number.isFinite(stock)||stock<=0)return null;
 return arcs.map((arc,i)=>({i:i+1,arc,width:arc/n,trim:stock-arc/n,flag:arc/n>stock?'Troppo largo':arc/n<stock/2?'Molto stretto':'Compatibile'}));
}
function readArcs(t){return t.trim().split(/[\s;]+/).filter(Boolean).map(x=>/^\d+(?:[.,]\d+)?$/.test(x)?Number(x.replace(',','.')):NaN)}
function estimateLayer(n,avg,stock,waste,sides){return [n,avg,stock,waste,sides].every(Number.isFinite)&&Number.isInteger(n)&&n>0&&avg>0&&stock>0&&waste>=0&&waste<=100&&[1,2].includes(sides)?Math.ceil(n*avg*sides*(1+waste/100)/stock):null}
function sailSize(base,top,height,den){return [base,top,height,den].every(Number.isFinite)&&base>0&&top>=0&&height>0&&Number.isInteger(den)&&den>0?{base:base*1000/den,top:top*1000/den,height:height*1000/den,area:(base+top)*height/2*1000000/(den*den)}:null}
function labField(id,label,value,step='any',min=0){return '<label for="'+id+'">'+label+'</label><input type="number" id="'+id+'" value="'+value+'" step="'+step+'" min="'+min+'">'}
function labPanel(){
return '<h1 class="spaced">Laboratorio tecnico</h1><p>Misure di modello in mm, salvo indicazione. I valori iniziali sono esempi modificabili, non quote del tuo kit.</p>'+
'<section class="card"><h2>1 · Piano di rastrematura</h2><p>Misura lo sviluppo curvo di una fascia, su ciascuna ordinata dello stesso lato. Inserisci i valori da prua a poppa, separati da spazi o a capo. Usa la virgola o il punto per i decimali.</p><label for="labArcs">Archi delle ordinate (mm)</label><textarea id="labArcs">36 44 55 60 60 54 45</textarea>'+labField('labN','Corsi nella fascia',12,'1',1)+labField('labStock','Larghezza del listello grezzo (mm)',6,'any',0.01)+'<div id="labPlan" aria-live="polite"></div><small>La larghezza media è arco ÷ corsi. Se i corsi diventano troppo stretti o larghi, rivedi le fasce o valuta corsi interrotti e inserti secondo il piano. Il profilo è indicativo, con ordinate equidistanti; non è una dima da taglio.</small></section>'+
'<section class="card"><h2>2 · Stima legno: primo e secondo fasciame</h2><p>Inserisci il numero totale di corsi per lato e la lunghezza media effettiva di un corso, non la lunghezza della nave. Calcola separatamente i due strati.</p><h3>Primo fasciame</h3>'+labField('l1n','Corsi per lato',20,'1',1)+labField('l1avg','Lunghezza media corso (mm)',450)+labField('l1stock','Lunghezza listello commerciale (mm)',500)+labField('l1w','Larghezza listello (mm)',5)+labField('l1t','Spessore listello (mm)',1.5)+labField('l1loss','Scarto aggiuntivo (%)',15)+ '<div id="l1res" aria-live="polite"></div><h3 class="spaced">Secondo fasciame</h3>'+labField('l2n','Corsi per lato',24,'1',1)+labField('l2avg','Lunghezza media corso (mm)',450)+labField('l2stock','Lunghezza listello commerciale (mm)',500)+labField('l2w','Larghezza listello (mm)',4)+labField('l2t','Spessore listello (mm)',0.5)+labField('l2loss','Scarto aggiuntivo (%)',20)+'<div id="l2res" aria-live="polite"></div><small>Stima lineare per due lati: verifica disponibilità delle lunghezze, giunzioni, tagli e venatura. Per un kit a strato singolo considera solo il primo. Il volume indica il legno acquistato, non il volume dello scafo.</small></section>'+
'<section class="card"><h2>3 · Convertire una misura tra due scale</h2>'+labField('labSize','Misura sul modello di partenza (mm)',100)+labField('labFrom','Scala di partenza (1:N)',64,'1',1)+labField('labTo','Scala di arrivo (1:N)',80,'1',1)+'<div id="labScale" class="big" aria-live="polite"></div></section>'+
'<section class="card"><h2>4 · Disegnare una vela triangolare o trapezoidale</h2><p>Inserisci le misure reali in metri. Per una vela triangolare imposta la base superiore a zero. Per il trapezio le due basi devono essere parallele e l’altezza perpendicolare.</p>'+labField('sBase','Base inferiore reale (m)',6)+labField('sTop','Base superiore reale (m)',2)+labField('sHeight','Altezza reale (m)',5)+labField('sDen','Scala (1:N)',64,'1',1)+'<div id="labSail" aria-live="polite"></div><small>Schema geometrico centrato, non sagoma storica. Aggiungi separatamente orli, curvatura e abbondanze secondo i piani.</small></section>';
}
function runLab(){
 if(!$('labArcs'))return;
 const v=id=>$(id).value.trim()===''?NaN:Number($(id).value),valid='Inserisci misure valide.';
 const rows=planWidths(readArcs($('labArcs').value),v('labN'),v('labStock'));
 if(!rows)$('labPlan').textContent='Inserisci da 2 a 30 archi positivi, corsi interi e larghezza positiva.';
 else{
 const max=Math.max(...rows.map(r=>r.width),v('labStock')), dx=240/(rows.length-1),px=i=>30+i*dx,py=w=>115-85*w/max;
 const points=rows.map((r,i)=>px(i).toFixed(2)+','+py(r.width).toFixed(2)).join(' ');
 $('labPlan').innerHTML='<svg class="diagram" viewBox="0 0 300 145" role="img" aria-label="Profilo indicativo della larghezza dei corsi"><path d="M30 115H270" stroke="#795738" fill="none"/><path d="M30 '+py(v('labStock'))+'H270" stroke="#ae8650" stroke-dasharray="4 3"/><polyline points="'+points+'" stroke="#286d6a" stroke-width="3" fill="none"/>'+rows.map((r,i)=>'<circle cx="'+px(i)+'" cy="'+py(r.width)+'" r="3" fill="#286d6a"/>').join('')+'<text x="150" y="137" text-anchor="middle" font-size="11">Prua → ordinate → poppa</text></svg><small>Linea tratteggiata: larghezza grezza.</small><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px;text-align:left"><thead><tr><th>Ord.</th><th>Arco</th><th>Corso</th><th>Asporta</th><th>Esito</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+r.i+'</td><td>'+fmt(r.arc)+'</td><td>'+fmt(r.width)+'</td><td>'+(r.trim<0?'—':fmt(r.trim))+'</td><td>'+r.flag+'</td></tr>').join('')+'</tbody></table></div>';
 }
 for(const p of ['l1','l2']){
 const n=v(p+'n'),avg=v(p+'avg'),stock=v(p+'stock'),w=v(p+'w'),t=v(p+'t'),loss=v(p+'loss'),count=estimateLayer(n,avg,stock,loss,2);
 $(p+'res').innerHTML=count===null||!(w>0&&t>0&&Number.isFinite(w*t*count*stock))?valid:'<div class="big">'+fmt(count)+' listelli</div><p>Metri da acquistare: '+fmt(count*stock/1000)+' m<br>Volume indicativo: '+fmt(count*stock*w*t/1000)+' cm³</p>';
 }
 const size=v('labSize'),from=v('labFrom'),to=v('labTo');
 $('labScale').textContent=[size,from,to].every(Number.isFinite)&&size>0&&Number.isInteger(from)&&Number.isInteger(to)&&from>0&&to>0?fmt(size*from/to)+' mm':valid;
 const sail=sailSize(v('sBase'),v('sTop'),v('sHeight'),v('sDen'));
 if(!sail)$('labSail').textContent=valid;
 else{
 const k=Math.min(240/Math.max(sail.base,sail.top),85/sail.height),b=sail.base*k/2,t=sail.top*k/2;
 $('labSail').innerHTML='<svg class="diagram" viewBox="0 0 300 145" role="img" aria-label="Schema geometrico della vela"><polygon points="'+(150-b)+',110 '+(150+b)+',110 '+(150+t)+','+(110-sail.height*k)+' '+(150-t)+','+(110-sail.height*k)+'" fill="#d4b28b" stroke="#795738" stroke-width="2"/><path d="M150 110V'+(110-sail.height*k)+'" stroke="#286d6a" stroke-dasharray="4 3"/><text x="150" y="137" text-anchor="middle" font-size="11">Schema proporzionale</text></svg><p>Base inferiore: <b>'+fmt(sail.base)+' mm</b><br>Base superiore: <b>'+fmt(sail.top)+' mm</b><br>Altezza: <b>'+fmt(sail.height)+' mm</b><br>Superficie geometrica: <b>'+fmt(sail.area/100)+' cm²</b></p>';
 }
}
document.addEventListener('input',e=>{if(tab==='tools'&&$('labArcs'))runLab()});

function tools(){return `<h1>Calcolatori</h1><p class="muted">Misure in millimetri, salvo indicazione diversa. I risultati sono orientativi.</p><div class="card"><h2>Scala del modello</h2><label for="real">Misura reale (metri)</label><input id="real" type="number" min="0" step="any" value="40"><label for="den">Denominatore della scala</label><input id="den" type="number" min="1" step="1" value="64"><div class="big" id="scaleResult" aria-live="polite">625 mm · 62,5 cm</div></div><div class="card"><h2>Rastrematura del fasciame</h2><p>Misura l’arco da coprire su una singola ordinata e dividi per il numero di corsi previsti.</p><label for="arc">Arco da rivestire (mm)</label><input id="arc" type="number" min="0" step="any" value="60"><label for="courses">Numero di corsi</label><input id="courses" type="number" min="1" step="1" value="12"><label for="stock">Larghezza del listello disponibile (mm)</label><input id="stock" type="number" min="0" step="any" value="6"><div id="taperResult" class="big" aria-live="polite">5 mm</div><p id="taperNote">Riduzione: 1 mm per listello.</p></div><div class="card"><h2>Cordame in scala</h2><label for="rope">Diametro reale (mm)</label><input id="rope" type="number" min="0" step="any" value="40"><label for="ropeDen">Denominatore scala</label><input id="ropeDen" type="number" min="1" step="1" value="64"><div id="ropeResult" class="big" aria-live="polite">0,63 mm</div></div><div class="card"><h2>Stima listelli da acquistare</h2><label for="required">Lunghezza totale stimata dei corsi (m)</label><input id="required" type="number" min="0" step="any" value="12"><label for="strip">Lunghezza di un listello (mm)</label><input id="strip" type="number" min="1" step="any" value="500"><label for="waste">Scarto aggiuntivo (%)</label><input id="waste" type="number" min="0" step="any" value="15"><div id="stripResult" class="big" aria-live="polite">28 listelli</div><small>Stima lineare: verifica anche tagli, giunzioni e larghezze.</small></div>`+labPanel()}

function backupSummary(){
 const bytes=new Blob([JSON.stringify(state)]).size,photos=state.projects.reduce((n,p)=>n+p.logs.filter(l=>l.photo).length,0);
 return '<div class="grid"><div><small>Navi</small><div class="big">'+state.projects.length+'</div></div><div><small>Foto nel diario</small><div class="big">'+photos+'</div></div><div><small>Percorsi</small><div class="big">'+tutorCourses().length+'</div></div></div><p>Dimensione dati JSON: circa '+fmt(bytes/1024)+' KB (non è la quota del browser). Salva una copia su un dispositivo o in una cartella sicura prima di importare un backup o cancellare i dati del sito.</p>';
}

function settings(){return `<h1>Altro</h1><div class="card"><h2>Come vuoi usare l’app?</h2><p>Modalità semplice: meno pulsanti e spiegazioni per principianti. Modalità completa: tutte le opzioni tecniche.</p>${modeButton()}</div><div class="card"><h2>Privacy e informazioni</h2><p>Il diario, le fotografie e i progressi restano nella memoria locale di questo browser. Non vengono sincronizzati su un server dell’app. Il convertitore HEIC scarica una libreria esterna; i siti collegati, incluso ChatGPT, hanno condizioni e privacy proprie. L’hosting può registrare richieste di rete. Prima di condividere immagini, rimuovi informazioni personali.</p><p><a href="privacy.html" target="_blank" rel="noopener noreferrer">Informativa sulla versione web ↗</a></p><small>Versione candidata al rilascio: non ancora approvata dagli store.</small></div><div class="card"><h2>Enciclopedia delle navi</h2><button data-go="catalog">Esplora i modelli</button></div><div class="card"><h2>Dizionario navale</h2><label for="search">Cerca un termine</label><input id="search" type="search" placeholder="Es. quartabuono"><div id="glossary">${glossaryHTML('')}</div></div><div class="card"><h2>Backup dei tuoi dati</h2>${backupSummary()}<p>I progetti e le foto sono conservati sul dispositivo, nel browser. Esporta periodicamente un backup JSON. Cancellare i dati del sito può far perdere il diario.</p><div class="row"><button data-export>Esporta backup</button><button class="secondary" data-import>Importa backup</button></div><input id="backupFile" type="file" accept="application/json,.json" hidden></div><div class="card"><h2>Installazione</h2><p>Pubblica i file su un hosting HTTPS. In Chrome Android apri il menu ⋮ e scegli Installa app o Aggiungi a schermata Home. Su iPhone usa Safari → Condividi → Aggiungi alla schermata Home.</p><small>Versione 8.0 RC · Il convertitore HEIC richiede Internet al primo caricamento della libreria; le immagini vengono elaborate nel browser. Nessun account o servizio a pagamento. Betta Modellista usa regole locali; non analizza foto automaticamente. Il confronto automatico dei prezzi non è incluso.</small></div>`}
function glossaryHTML(q){const s=q.trim().toLowerCase();return glossary.filter(x=>x.join(' ').toLowerCase().includes(s)).map(x=>`<div class="step"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')||'<p>Nessun termine trovato.</p>'}
function calculate(){const val=id=>$(id).value.trim()===''?NaN:num($(id).value);const positive=x=>Number.isFinite(x)&&x>0;const a=val('real'),b=val('den');$('scaleResult').textContent=positive(a)&&positive(b)&&Number.isInteger(b)?`${fmt(a*1000/b)} mm · ${fmt(a*100/b)} cm`:'Inserisci misure valide';const arc=val('arc'),n=val('courses'),stock=val('stock');if(positive(arc)&&positive(n)&&Number.isInteger(n)&&positive(stock)){const w=arc/n;$('taperResult').textContent=fmt(w)+' mm';$('taperNote').textContent=w>stock?'Il corso richiesto supera la larghezza disponibile: rivedi la distribuzione.':`Riduzione: ${fmt(stock-w)} mm per listello.`+(w<stock/2?' Attenzione: valuta una diversa distribuzione dei corsi.':'')}else{$('taperResult').textContent='Inserisci misure valide';$('taperNote').textContent=''}const r=val('rope'),rd=val('ropeDen');$('ropeResult').textContent=positive(r)&&positive(rd)&&Number.isInteger(rd)?fmt(r/rd)+' mm':'Inserisci misure valide';const req=val('required'),strip=val('strip'),waste=val('waste');$('stripResult').textContent=positive(req)&&positive(strip)&&Number.isFinite(waste)&&waste>=0?`${fmt(Math.ceil(req*1000*(1+waste/100)/strip))} listelli`:'Inserisci misure valide'}
let heicLoader;
function loadHeic(){
  if(typeof window.HeicTo==='function')return Promise.resolve(window.HeicTo);
  if(!heicLoader)heicLoader=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='https://cdn.jsdelivr.net/npm/heic-to@1.6.7/dist/iife/heic-to.js';
    const fail=()=>{clearTimeout(timer);script.remove();heicLoader=null;reject(Error('Convertitore HEIC non disponibile. Collegati a Internet e riprova, oppure scegli una foto JPG.'))};
    const timer=setTimeout(fail,30000);
    script.onerror=fail;
    script.onload=()=>{if(typeof window.HeicTo!=='function'){fail();return}clearTimeout(timer);resolve(window.HeicTo)};
    document.head.appendChild(script);
  });
  return heicLoader;
}
function resizePhoto(file){return new Promise((resolve,reject)=>{const im=new Image(),url=URL.createObjectURL(file);im.onload=()=>{try{const c=document.createElement('canvas'),f=Math.min(1,1000/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*f));c.height=Math.max(1,Math.round(im.height*f));c.getContext('2d').drawImage(im,0,0,c.width,c.height);const result=c.toDataURL('image/jpeg',.7);if(!result.startsWith('data:image/jpeg;base64,'))throw Error('Conversione JPEG non riuscita.');resolve(result)}catch(e){reject(e)}finally{URL.revokeObjectURL(url)}};im.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Impossibile leggere la foto. Prova con JPG o PNG.'))};im.src=url})}
async function photo(file){
  if(!file||!file.size)return '';
  if(file.size>25*1024*1024)throw Error('Foto troppo grande (max 25 MB).');
  try{return await resizePhoto(file)}catch(err){
    if(!/\.(heic|heif|heics|heifs)$/i.test(file.name||'')&&!/image\/(heic|heif)/i.test(file.type||''))throw err;
  }
  notice('Conversione della foto HEIC in corso…');
  const convert=await loadHeic();
  let jpeg;
  try{jpeg=await convert({blob:file,type:'image/jpeg',quality:0.8})}catch(err){throw Error('Questa foto HEIC non è convertibile. Prova con una copia JPG o PNG.')}
  return resizePhoto(jpeg);
}
function validBackup(s){if(s&&s.academyQuiz!==undefined&&(!s.academyQuiz||typeof s.academyQuiz!=='object'||Array.isArray(s.academyQuiz)||Object.entries(s.academyQuiz).some(([k,v])=>!/^\d+$/.test(k)||String(Number(k))!==k||Number(k)>=lessons.length||v!==true)))return false;if(s&&s.scratchCourses!==undefined&&(!Array.isArray(s.scratchCourses)||!s.scratchCourses.every(tutorValid)))return false;const str=x=>typeof x==='string',nat=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0;return s&&Array.isArray(s.projects)&&Array.isArray(s.done)&&s.done.every(i=>Number.isInteger(i)&&i>=0&&i<lessons.length)&&s.projects.every(p=>p&&str(p.id)&&/^[a-zA-Z0-9-]+$/.test(p.id)&&str(p.name)&&str(p.maker)&&['£','€','$'].includes(p.currency)&&(p.scale===''||nat(p.scale))&&Array.isArray(p.completed)&&p.completed.every(i=>Number.isInteger(i)&&i>=0&&i<stages.length)&&Array.isArray(p.logs)&&p.logs.every(l=>l&&str(l.id)&&str(l.date)&&str(l.note)&&nat(l.hours)&&nat(l.cost)&&str(l.photo)&&(!l.photo||/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(l.photo))))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.tab||d.go){go(d.tab||d.go);return}if(d.project!==undefined){projectId=d.project;render();window.scrollTo(0,0)}else if(d.lesson!==undefined){lessonId=num(d.lesson);render();window.scrollTo(0,0)}else if(d.complete!==undefined){const i=num(d.complete),was=state.done.includes(i);const previous=state.done;state.done=was?state.done.filter(x=>x!==i):[...state.done,i];if(!save()){state.done=previous;return}render();notice(was?'Lezione riaperta':'Lezione completata!')}else if(d.deleteProject!==undefined){if(confirm('Eliminare questo progetto e tutto il diario?')){const previous=state.projects;state.projects=state.projects.filter(p=>p.id!==projectId);if(!save()){state.projects=previous;return}go('projects')}}else if(d.deleteLog!==undefined){if(confirm('Eliminare questa annotazione?')){const p=state.projects.find(p=>p.id===projectId);const previous=p.logs;p.logs=p.logs.filter(l=>l.id!==d.deleteLog);if(!save()){p.logs=previous;return}render()}}else if(d.export!==undefined){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='naval-intelligence-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notice('Backup preparato')}else if(d.import!==undefined){$('backupFile').click()}});
document.addEventListener('input',e=>{if(tab==='tools'&&e.target.tagName==='INPUT')calculate();if(e.target.id==='search')$('glossary').innerHTML=glossaryHTML(e.target.value)});
document.addEventListener('change',async e=>{if(e.target.dataset.stage!==undefined){const p=state.projects.find(p=>p.id===projectId),i=num(e.target.dataset.stage);const previous=p.completed;p.completed=e.target.checked?[...new Set([...p.completed,i])]:p.completed.filter(x=>x!==i);if(!save()){p.completed=previous;render();return}render()}if(e.target.id==='backupFile'&&e.target.files.length){try{const f=e.target.files[0];if(f.size>15*1024*1024)throw Error('Backup troppo grande');const s=JSON.parse(await f.text());if(!validBackup(s))throw Error('Formato backup non valido');if(confirm('Backup: '+s.projects.length+' navi, '+s.done.length+' lezioni, '+(s.scratchCourses||[]).length+' percorsi. Sostituire tutti i dati locali? Esporta prima un backup dei dati attuali.')){const prev=state;state=s;if(!save()){state=prev;return}go('home');notice('Backup importato')}}catch(err){notice(err.message)}}});
document.addEventListener('submit',async e=>{if(!['newProject','newLog'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='newProject'){const name=String(f.get('name')).trim();if(!name){notice('Inserisci il nome');return}const p={id:uid(),name,maker:String(f.get('maker')).trim(),scale:f.get('scale')?num(f.get('scale')):'',currency:f.get('currency'),completed:[],logs:[]};state.projects.push(p);if(!save()){state.projects.pop();return}projectId=p.id;render();window.scrollTo(0,0);notice('Nave aggiunta al cantiere')}else{const p=state.projects.find(p=>p.id===projectId),note=String(f.get('note')).trim();if(!note)return;const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const l={id:uid(),date:today(),note,hours:num(f.get('hours')||0),cost:num(f.get('cost')||0),photo:await photo(f.get('photo'))};p.logs.push(l);if(!save()){p.logs.pop();return}render();notice('Annotazione salvata')}catch(err){notice(err.message||'Errore nel salvataggio')}finally{button.disabled=false}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('install').hidden=false});$('install').addEventListener('click',async()=>{if(installEvent){await installEvent.prompt();installEvent=null;$('install').hidden=true}});window.addEventListener('appinstalled',()=>{$('install').hidden=true});if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});render();
